-- Phase 2 — Schedule + Front Desk: patients, appointment texts, charting type.
--
-- The table / enum / column DDL below was GENERATED by `prisma migrate diff` from
-- the live database to schema.prisma, so it cannot disagree with the schema. The
-- section marked HAND-WRITTEN at the end is data, which Prisma cannot express.
--
-- Changes to existing tables are additive: three nullable-or-defaulted columns on
-- "Booking" (source defaults to ONLINE, which is exactly what every existing row
-- is) and one defaulted column on "Service". Nothing in the booking, availability
-- or locking logic reads any of them.

-- CreateEnum
CREATE TYPE "BookingSource" AS ENUM ('ONLINE', 'PHONE', 'WALK_IN', 'FRONT_DESK');

-- CreateEnum
CREATE TYPE "DocumentationType" AS ENUM ('SOAP', 'SESSION_LOG');

-- CreateEnum
CREATE TYPE "ContactMethod" AS ENUM ('PHONE', 'SMS', 'EMAIL');

-- CreateEnum
CREATE TYPE "MessageKind" AS ENUM ('CONFIRMATION', 'REMINDER_24H');

-- CreateEnum
CREATE TYPE "MessageStatus" AS ENUM ('QUEUED', 'SENT', 'FAILED', 'SKIPPED');

-- AlterTable
ALTER TABLE "Booking" ADD COLUMN     "createdByAccountId" TEXT,
ADD COLUMN     "patientId" TEXT,
ADD COLUMN     "source" "BookingSource" NOT NULL DEFAULT 'ONLINE';

-- AlterTable
ALTER TABLE "Service" ADD COLUMN     "documentationType" "DocumentationType" NOT NULL DEFAULT 'SESSION_LOG';

-- CreateTable
CREATE TABLE "Patient" (
    "id" TEXT NOT NULL,
    "firstName" TEXT NOT NULL,
    "lastName" TEXT NOT NULL,
    "preferredName" TEXT,
    "dateOfBirth" DATE,
    "sex" TEXT,
    "phone" TEXT NOT NULL,
    "phoneDigits" TEXT NOT NULL,
    "email" TEXT,
    "addressLine1" TEXT,
    "addressLine2" TEXT,
    "city" TEXT,
    "state" TEXT,
    "postalCode" TEXT,
    "emergencyName" TEXT,
    "emergencyPhone" TEXT,
    "emergencyRelation" TEXT,
    "preferredContact" "ContactMethod" NOT NULL DEFAULT 'PHONE',
    "smsOptIn" BOOLEAN NOT NULL DEFAULT false,
    "smsOptInAt" TIMESTAMP(3),
    "smsConsentRecordedById" TEXT,
    "frontDeskNote" TEXT,
    "createdById" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    "deletedAt" TIMESTAMP(3),

    CONSTRAINT "Patient_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "MessageLog" (
    "id" TEXT NOT NULL,
    "bookingId" TEXT NOT NULL,
    "patientId" TEXT,
    "kind" "MessageKind" NOT NULL,
    "forStart" TIMESTAMP(3) NOT NULL,
    "status" "MessageStatus" NOT NULL DEFAULT 'QUEUED',
    "templateId" TEXT NOT NULL,
    "attempts" INTEGER NOT NULL DEFAULT 0,
    "providerMessageId" TEXT,
    "failureCode" TEXT,
    "queuedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "sentAt" TIMESTAMP(3),
    "nextAttemptAt" TIMESTAMP(3),

    CONSTRAINT "MessageLog_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "Patient_lastName_firstName_idx" ON "Patient"("lastName", "firstName");

-- CreateIndex
CREATE INDEX "Patient_phoneDigits_idx" ON "Patient"("phoneDigits");

-- CreateIndex
CREATE INDEX "Patient_email_idx" ON "Patient"("email");

-- CreateIndex
CREATE INDEX "MessageLog_status_nextAttemptAt_idx" ON "MessageLog"("status", "nextAttemptAt");

-- CreateIndex
CREATE UNIQUE INDEX "MessageLog_bookingId_kind_forStart_key" ON "MessageLog"("bookingId", "kind", "forStart");

-- CreateIndex
CREATE INDEX "Booking_patientId_idx" ON "Booking"("patientId");

-- AddForeignKey
ALTER TABLE "Booking" ADD CONSTRAINT "Booking_patientId_fkey" FOREIGN KEY ("patientId") REFERENCES "Patient"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "MessageLog" ADD CONSTRAINT "MessageLog_bookingId_fkey" FOREIGN KEY ("bookingId") REFERENCES "Booking"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "MessageLog" ADD CONSTRAINT "MessageLog_patientId_fkey" FOREIGN KEY ("patientId") REFERENCES "Patient"("id") ON DELETE SET NULL ON UPDATE CASCADE;


-- =============================================================================
-- HAND-WRITTEN: which services are charted as a full SOAP note
-- =============================================================================
-- Owner's mapping (2026-10-10):
--   SOAP        chiropractic adjustment, chiropractic exam / new patient, NP
--               consult, functional medicine consult, IV therapy, injections,
--               bloodwork
--   SESSION_LOG HBOT, red light, body composition, and any other timed modality
--   ANYTHING NOT NAMED defaults to SESSION_LOG — the column default — and is listed
--   in docs/PHASE2_NOTES.md for the owner to confirm. It is editable per service in
--   the admin screen, so a wrong guess is a setting, not a deploy.
--
-- Matched by slug. On a brand-new database this runs BEFORE the seed, when the
-- Service table is empty, so it updates nothing; prisma/seed.ts therefore carries
-- the same mapping for fresh installs.
UPDATE "Service" SET "documentationType" = 'SOAP' WHERE "slug" IN (
  'manual-adjustment',           -- chiropractic adjustment
  'spinal-postural-exam',        -- chiropractic exam / new patient
  'functional-medicine-consult', -- functional medicine consult (an NP visit)
  'iv-therapy',                  -- IV therapy
  'vitamin-shots',               -- injections
  'biomarker-testing'            -- bloodwork
);
